DO $$
DECLARE fixtures jsonb:=current_setting('test.ticket_layout_fixtures')::jsonb; entry record; layout jsonb; changed jsonb; v_features jsonb;
  v_org bigint; v_unit bigint; v_oc bigint; v_copy bigint; v_editor uuid; v_stranger uuid; config jsonb; response jsonb; command uuid:=gen_random_uuid(); saved jsonb;
BEGIN
  FOR layout IN SELECT * FROM jsonb_array_elements(fixtures->'valid') LOOP PERFORM public.validate_ticket_layout(layout); END LOOP;
  FOR entry IN SELECT * FROM jsonb_each(fixtures->'invalid') LOOP
    BEGIN PERFORM public.validate_ticket_layout(entry.value); RAISE EXCEPTION 'accepted invalid fixture %',entry.key;
    EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'accepted invalid fixture%' THEN RAISE; END IF; END;
  END LOOP;
  PERFORM assert_eq(public.scan_ticket('VZOR:NEPLATNY','preview-only')->>'code','404','scanner rejects the synthetic preview QR');
  layout:=fixtures->'valid'->0;
  v_features:=jsonb_build_array(jsonb_build_object('code','ticket','is_enabled',true,'layout',layout));
  PERFORM assert_eq(public.merge_ticket_layout_features(v_features,'[{"code":"ticket","is_enabled":false}]')#>'{0,layout}',layout,'old client retains layout when disabled');
  PERFORM assert_eq(public.merge_ticket_layout_features(v_features,'[]')#>'{0,layout}',layout,'missing ticket feature retains disabled layout');
  PERFORM assert_eq(public.merge_ticket_layout_features(v_features,'[]')#>'{0,is_enabled}','false'::jsonb,'missing feature is disabled');
  changed:=jsonb_set(layout,'{templates,named,elements,0,box,x}','70');
  PERFORM create_user_for_test('layout_editor','layout_editor@test.local');
  PERFORM create_user_for_test('layout_stranger','layout_stranger@test.local');
  v_editor:=get_user_id('layout_editor');v_stranger:=get_user_id('layout_stranger');
  INSERT INTO public.organizations(title,data) VALUES('Ticket layout tests','{"IS_APP_SUPPORTED":true}') RETURNING id INTO v_org;
  INSERT INTO public.units(title,organization) VALUES('Layout unit',v_org) RETURNING id INTO v_unit;
  INSERT INTO public.unit_users(unit,"user",is_editor,is_manager) VALUES(v_unit,v_editor,true,true);
  INSERT INTO public.occasions(title,link,unit,organization,features,data,start_time,end_time) VALUES('Layout event','layout-'||gen_random_uuid(),v_unit,v_org,v_features,'{}',now(),now()+interval '1 day') RETURNING id INTO v_oc;
  PERFORM set_config('request.jwt.claim.role','authenticated',true);
  PERFORM set_config('request.jwt.claim.sub',v_editor::text,true);
  PERFORM assert_true(public.can_edit_ticket_layout(v_oc),'unit editor can preview');
  config:=jsonb_build_object('id',v_oc,'unit',v_unit,'title','Old client save','features','[]'::jsonb);
  PERFORM public.update_occasion_203(config);
  PERFORM assert_eq((SELECT features#>'{0,layout}' FROM public.occasions WHERE id=v_oc),layout,'legacy save retains layout');
  config:=config||jsonb_build_object('ticket_layout_change',jsonb_build_object('expected',layout,'next',changed));
  response:=public.save_occasion_client_sync_v1(v_oc,command,0,config);
  PERFORM assert_eq(response->>'status','applied','command save applies explicit change');
  PERFORM assert_eq((SELECT features#>'{0,layout}' FROM public.occasions WHERE id=v_oc),changed,'explicit change persists');
  saved:=public.save_occasion_client_sync_v1(v_oc,command,0,config);
  PERFORM assert_eq(saved,response,'same command is replayed');
  BEGIN
    PERFORM public.update_occasion_203(config||'{"title":"Must not persist"}');
    RAISE EXCEPTION 'stale edit accepted';
  EXCEPTION WHEN serialization_failure THEN NULL; END;
  PERFORM assert_eq((SELECT title FROM public.occasions WHERE id=v_oc),'Old client save','conflict does not partially save title');
  BEGIN
    PERFORM public.update_occasion_203(config||jsonb_build_object('ticket_layout_change',jsonb_build_object('expected',changed,'next','{}'::jsonb)));
    RAISE EXCEPTION 'malformed edit accepted';
  EXCEPTION WHEN OTHERS THEN IF SQLERRM='malformed edit accepted' THEN RAISE; END IF; END;
  PERFORM set_config('request.jwt.claim.sub',v_stranger::text,true);
  PERFORM assert_true(NOT public.can_edit_ticket_layout(v_oc),'foreign unit cannot preview');
  BEGIN PERFORM public.update_occasion_203(config);RAISE EXCEPTION 'unauthorized save accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  PERFORM set_config('request.jwt.claim.sub',v_editor::text,true);
  SELECT public.duplicate_occasion(v_oc) INTO v_copy;
  PERFORM assert_eq((SELECT features#>'{0,layout}' FROM public.occasions WHERE id=v_copy),changed,'duplicate retains geometry');
  PERFORM assert_true(NOT has_column_privilege('authenticated','public.occasions','features','UPDATE'),'direct update cannot bypass save');
  PERFORM assert_true(NOT has_column_privilege('authenticated','public.occasions','features','INSERT'),'direct insert cannot bypass validation');
  PERFORM public.update_occasion_203(jsonb_build_object('unit',v_unit,'organization',v_org,'title','Created with layout','link','created-layout-'||gen_random_uuid(),'features',v_features,'start_time',now(),'end_time',now()+interval '1 day'));
  PERFORM assert_true(EXISTS(SELECT 1 FROM public.occasions WHERE title='Created with layout' AND features#>'{0,layout}'=layout),'create validates and stores layout');
END $$;
ROLLBACK;
